import { useState, useEffect, useRef, useCallback } from 'react'
import {
  useTournamentStore,
  type TournamentStage,
  type CustomStageConfig,
  type TournamentTemplate,
  STAGE_LABELS,
  STAGE_ORDER,
  STAGE_ADVANCE_COUNT,
} from '@/store/tournamentStore'
import { QRCodeSVG } from 'qrcode.react'
import { Trophy, Lock, Unlock, ChevronRight, RotateCcw, Play, Save, Users, ArrowRight, Download, Upload, Clock, History, Trash2, Eye, X, LayoutList, Plus, Minus, Hash, FolderOpen, FolderPlus, Edit3, QrCode } from 'lucide-react'

interface TournamentControlProps {
  onSwitchPage?: (target: 'home' | 'selector' | 'tournament') => void
}

export default function TournamentControl({ onSwitchPage }: TournamentControlProps) {
  const {
    stages,
    currentStage,
    isTournamentStarted,
    isCustomMode,
    customStages,
    setPlayerNames,
    updatePlayer,
    toggleStageLock,
    calculateRankings,
    resetTournament,
    startTournament,
    setCurrentStage,
    broadcastTournamentData,
    exportTournamentData,
    importTournamentData,
    saveToHistory,
    loadHistory,
    deleteHistoryRecord,
    clearHistory,
    timerRunning,
    timerSeconds,
    timerLabel,
    startTimer,
    stopTimer,
    resetTimer,
    setCustomMode,
    setCustomStages,
    setPlayerSeed,
    applySeeding,
    saveTemplate,
    loadTemplate,
    deleteTemplate,
    getTemplates,
  } = useTournamentStore()

  const [playerNameInput, setPlayerNameInput] = useState('')
  const [bulkNameInput, setBulkNameInput] = useState('')
  const [useBulkMode, setUseBulkMode] = useState(false)
  const [showHistory, setShowHistory] = useState(false)
  const [timerInputMin, setTimerInputMin] = useState(0)
  const [timerInputSec, setTimerInputSec] = useState(0)
  const [timerCustomLabel, setTimerCustomLabel] = useState('')
  const [checkinNames, setCheckinNames] = useState<string[]>([])
  const [showCheckInPanel, setShowCheckInPanel] = useState(false)
  const fileInputRef = useRef<HTMLInputElement>(null)
  const timerIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const checkinChannelRef = useRef<BroadcastChannel | null>(null)

  // Custom stage editor state
  const [editingStages, setEditingStages] = useState<CustomStageConfig[]>([])
  const [showTemplateManager, setShowTemplateManager] = useState(false)
  const [templates, setTemplates] = useState<TournamentTemplate[]>([])
  const [templateNameInput, setTemplateNameInput] = useState('')
  const [showCustomStageEditor, setShowCustomStageEditor] = useState(false)

  // Timer tick effect
  useEffect(() => {
    if (timerRunning) {
      timerIntervalRef.current = setInterval(() => {
        useTournamentStore.getState().tickTimer()
      }, 1000)
    } else if (timerIntervalRef.current) {
      clearInterval(timerIntervalRef.current)
      timerIntervalRef.current = null
    }
    return () => {
      if (timerIntervalRef.current) {
        clearInterval(timerIntervalRef.current)
      }
    }
  }, [timerRunning])

  // 加载模板列表
  useEffect(() => {
    if (showTemplateManager) {
      setTemplates(getTemplates())
    }
  }, [showTemplateManager, getTemplates])

  // 同步自定义阶段编辑状态
  useEffect(() => {
    setEditingStages(customStages)
  }, [customStages])

  // Listen for check-in events from other tabs
  useEffect(() => {
    checkinChannelRef.current = new BroadcastChannel('tournament-sync')
    checkinChannelRef.current.onmessage = (event) => {
      if (event.data?.type === 'checkin' && event.data.payload?.name) {
        const name = event.data.payload.name as string
        setCheckinNames(prev => {
          // 避免重复签到
          if (prev.includes(name)) return prev
          return [...prev, name]
        })
      }
    }
    return () => {
      checkinChannelRef.current?.close()
    }
  }, [])

  const handleStartTournament = () => {
    const n216Players = stages.n216.players
    if (n216Players.length === 0) {
      alert('请至少为 N进16 添加选手')
      return
    }
    startTournament(['n216'])
  }

  const handleBulkAddPlayers = () => {
    const names = bulkNameInput
      .split('\n')
      .map((n) => n.trim())
      .filter((n) => n.length > 0)
    if (names.length === 0) return
    setPlayerNames(currentStage, names)
    setBulkNameInput('')
  }

  const handleAddSinglePlayer = () => {
    const name = playerNameInput.trim()
    if (!name) return
    const existingNames = stages[currentStage].players.map((p) => p.name)
    setPlayerNames(currentStage, [...existingNames, name])
    setPlayerNameInput('')
  }

  const handleScoreChange = (playerId: string, value: string) => {
    if (value === '') {
      updatePlayer(currentStage, playerId, { score: null })
      return
    }
    const num = parseFloat(value)
    if (!isNaN(num) && num >= 0 && num <= 500) {
      updatePlayer(currentStage, playerId, { score: num })
    }
  }

  const handleCalculateRankings = () => {
    calculateRankings(currentStage)
  }

  const handleBroadcast = () => {
    broadcastTournamentData()
  }

  const handleReset = () => {
    if (confirm('确定要重置整个赛事吗？所有数据将被清除。')) {
      resetTournament()
    }
  }

  const handleNextStage = () => {
    const stageIdx = STAGE_ORDER.indexOf(currentStage)
    const nextStage = STAGE_ORDER[stageIdx + 1]
    if (nextStage) {
      setCurrentStage(nextStage as TournamentStage)
      setTimeout(() => broadcastTournamentData(), 100)
    }
  }

  // Export tournament data as JSON file
  const handleExport = () => {
    const json = exportTournamentData()
    const blob = new Blob([json], { type: 'application/json' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `tournament-${new Date().toISOString().slice(0, 10)}.json`
    a.click()
    URL.revokeObjectURL(url)
  }

  // Import tournament data from JSON file
  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = (ev) => {
      try {
        const json = ev.target?.result as string
        importTournamentData(json)
        alert('导入成功！')
      } catch {
        alert('导入失败，文件格式不正确')
      }
    }
    reader.readAsText(file)
    // Reset input
    e.target.value = ''
  }

  // Save to history
  const handleSaveHistory = () => {
    saveToHistory()
    alert('已保存到历史记录！')
  }

  // Handle timer start
  const handleStartTimer = () => {
    const totalSeconds = timerInputMin * 60 + timerInputSec
    if (totalSeconds <= 0) return
    startTimer(timerCustomLabel || '计时', totalSeconds)
  }

  // Format seconds to mm:ss
  const formatTime = useCallback((seconds: number) => {
    const m = Math.floor(seconds / 60)
    const s = seconds % 60
    return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`
  }, [])

  // Get history list
  const historyList = showHistory ? loadHistory() : []

  // 获取当前阶段晋级人数（支持自定义阶段）
  const getAdvanceCount = (stage: string): number => {
    const custom = customStages.find((c) => c.id === stage)
    if (custom) return custom.advanceCount
    return STAGE_ADVANCE_COUNT[stage as TournamentStage] ?? 0
  }

  // 获取当前阶段显示名称（支持自定义阶段）
  const getStageLabel = (stage: string): string => {
    const custom = customStages.find((c) => c.id === stage)
    if (custom) return custom.name
    return STAGE_LABELS[stage as TournamentStage] ?? stage
  }

  // ========== 自定义阶段编辑器操作 ==========

  const handleAddCustomStage = () => {
    const newStage: CustomStageConfig = {
      id: `custom-stage-${Date.now()}`,
      name: `新阶段 ${editingStages.length + 1}`,
      playerCount: 16,
      advanceCount: 8,
    }
    setEditingStages([...editingStages, newStage])
  }

  const handleRemoveCustomStage = (id: string) => {
    setEditingStages(editingStages.filter((s) => s.id !== id))
  }

  const handleUpdateCustomStage = (id: string, field: keyof CustomStageConfig, value: string | number) => {
    setEditingStages(editingStages.map((s) => (s.id === id ? { ...s, [field]: value } : s)))
  }

  const handleSaveCustomStages = () => {
    // 验证：每个阶段的 advanceCount 必须 <= playerCount
    const invalid = editingStages.find((s) => s.advanceCount > s.playerCount || s.playerCount <= 0 || s.advanceCount <= 0)
    if (invalid) {
      alert(`阶段 "${invalid.name}" 配置无效：晋级人数必须 ≤ 参赛人数，且都必须 > 0`)
      return
    }
    setCustomStages(editingStages)
    setShowCustomStageEditor(false)
    alert('自定义赛制已保存！')
  }

  const handleCancelCustomStageEdit = () => {
    setEditingStages(customStages)
    setShowCustomStageEditor(false)
  }

  // ========== 种子排名操作 ==========

  const handleApplySeeding = () => {
    if (stages[currentStage].players.length < 2) {
      alert('至少需要 2 名选手才能应用种子排序')
      return
    }
    applySeeding(currentStage)
    alert('种子排序已应用！')
  }

  // ========== 模板操作 ==========

  const handleSaveTemplate = () => {
    if (!templateNameInput.trim()) {
      alert('请输入模板名称')
      return
    }
    saveTemplate(templateNameInput.trim())
    setTemplateNameInput('')
    setTemplates(getTemplates())
    alert('模板已保存！')
  }

  const handleLoadTemplate = (id: string) => {
    if (confirm('加载模板将覆盖当前赛事配置，确定继续吗？')) {
      loadTemplate(id)
      setShowTemplateManager(false)
      alert('模板已加载！')
    }
  }

  const handleDeleteTemplate = (id: string) => {
    if (confirm('确定删除此模板吗？')) {
      deleteTemplate(id)
      setTemplates(getTemplates())
    }
  }

  // ========== 自定义赛制切换 ==========

  const handleToggleCustomMode = (enabled: boolean) => {
    if (enabled) {
      // 切换到自定义模式时，如果还没有自定义阶段，初始化一个默认配置
      if (customStages.length === 0) {
        const defaultCustom: CustomStageConfig[] = [
          { id: 'round1', name: 'N进16', playerCount: 24, advanceCount: 16 },
          { id: 'round2', name: '16进8', playerCount: 16, advanceCount: 8 },
          { id: 'round3', name: '8进4', playerCount: 8, advanceCount: 4 },
          { id: 'round4', name: '半决赛', playerCount: 4, advanceCount: 2 },
          { id: 'round5', name: '决赛', playerCount: 2, advanceCount: 1 },
        ]
        setEditingStages(defaultCustom)
        setCustomStages(defaultCustom)
      } else {
        setEditingStages(customStages)
      }
    }
    setCustomMode(enabled)
  }

  const stageData = stages[currentStage]
  const stageIndex = STAGE_ORDER.indexOf(currentStage)
  const advanceCount = getAdvanceCount(currentStage)
  const stageLabel = getStageLabel(currentStage)

  if (!isTournamentStarted) {
    return (
      <div className="max-w-4xl mx-auto px-4 py-8">
        <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700">
          <h2 className="text-2xl font-bold text-white mb-6 flex items-center gap-3">
            <Trophy className="text-yellow-400" size={28} />
            赛事设置
          </h2>

          {/* 赛制模式切换 */}
          <div className="mb-6 p-4 bg-gray-900/50 rounded-xl border border-gray-700">
            <h3 className="text-sm font-semibold text-gray-400 mb-3">赛制模式</h3>
            <div className="flex gap-3">
              <button
                onClick={() => handleToggleCustomMode(false)}
                className={`flex-1 px-4 py-3 rounded-xl font-bold transition-all flex items-center justify-center gap-2 ${
                  !isCustomMode
                    ? 'bg-gradient-to-r from-blue-500 to-blue-600 text-white shadow-lg'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                <LayoutList size={18} /> 固定赛制
              </button>
              <button
                onClick={() => handleToggleCustomMode(true)}
                className={`flex-1 px-4 py-3 rounded-xl font-bold transition-all flex items-center justify-center gap-2 ${
                  isCustomMode
                    ? 'bg-gradient-to-r from-purple-500 to-purple-600 text-white shadow-lg'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                <Edit3 size={18} /> 自定义赛制
              </button>
            </div>
            {isCustomMode && (
              <div className="mt-3">
                <button
                  onClick={() => {
                    setEditingStages(customStages)
                    setShowCustomStageEditor(true)
                  }}
                  className="w-full px-4 py-2 rounded-lg bg-purple-600/30 text-purple-300 border border-purple-500/30 hover:bg-purple-600/50 transition-colors flex items-center justify-center gap-2"
                >
                  <LayoutList size={16} /> 编辑自定义阶段
                </button>
                {customStages.length > 0 && (
                  <div className="mt-2 flex flex-wrap gap-2">
                    {customStages.map((s) => (
                      <span key={s.id} className="px-2 py-1 rounded bg-gray-700 text-gray-300 text-xs">
                        {s.name} ({s.playerCount}人 → {s.advanceCount}人)
                      </span>
                    ))}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* 模板管理 */}
          <div className="mb-6 p-4 bg-gray-900/50 rounded-xl border border-gray-700">
            <h3 className="text-sm font-semibold text-gray-400 mb-3">赛事模板</h3>
            <div className="flex gap-2 mb-3">
              <input
                type="text"
                value={templateNameInput}
                onChange={(e) => setTemplateNameInput(e.target.value)}
                placeholder="输入模板名称"
                className="flex-1 px-3 py-2 rounded-lg bg-gray-800 border border-gray-600 text-white text-sm placeholder-gray-500 focus:outline-none focus:border-blue-500"
              />
              <button
                onClick={handleSaveTemplate}
                className="px-4 py-2 rounded-lg bg-green-600 text-white font-bold hover:bg-green-700 transition-colors flex items-center gap-2 text-sm"
              >
                <FolderPlus size={14} /> 保存模板
              </button>
              <button
                onClick={() => {
                  setTemplates(getTemplates())
                  setShowTemplateManager(true)
                }}
                className="px-4 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors flex items-center gap-2 text-sm"
              >
                <FolderOpen size={14} /> 管理模板
              </button>
            </div>
          </div>

          {/* 选手扫码签到 */}
          <div className="mb-6 p-4 bg-gray-900/50 rounded-xl border border-gray-700">
            <h3 className="text-sm font-semibold text-gray-400 mb-3">选手扫码签到</h3>
            <div className="flex gap-2 mb-3">
              <button
                onClick={() => setShowCheckInPanel(true)}
                className="flex-1 px-4 py-2 rounded-lg bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-bold hover:from-cyan-600 hover:to-blue-700 transition-all flex items-center justify-center gap-2 text-sm"
              >
                <QrCode size={16} /> 打开签到面板
              </button>
            </div>
            {checkinNames.length > 0 && (
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <span className="text-sm text-cyan-400 font-semibold">已签到 {checkinNames.length} 人</span>
                  <button
                    onClick={() => {
                      // 将签到选手添加到 n216 列表
                      const targetStage = 'n216' as const
                      const existingNames = stages[targetStage].players.map((p) => p.name)
                      const newNames = checkinNames.filter((n) => !existingNames.includes(n))
                      const allNames = [...existingNames, ...newNames]
                      setPlayerNames(targetStage, allNames)
                      setCheckinNames([])
                      alert(`已将 ${newNames.length} 名签到选手添加到列表！`)
                    }}
                    className="px-3 py-1.5 rounded-lg bg-green-600/30 text-green-300 border border-green-500/30 hover:bg-green-600/50 transition-colors text-sm font-bold"
                  >
                    添加到选手列表
                  </button>
                </div>
                <div className="flex flex-wrap gap-1.5">
                  {checkinNames.map((name, idx) => {
                    const isExisting = stages.n216.players.some((p) => p.name === name)
                    return (
                      <span
                        key={idx}
                        className={`px-2 py-0.5 rounded-full text-xs ${
                          isExisting
                            ? 'bg-green-600/30 text-green-300'
                            : 'bg-cyan-600/30 text-cyan-300'
                        }`}
                      >
                        {isExisting ? '✓ ' : ''}{name}
                      </span>
                    )
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Import/Export section */}
          <div className="mb-6 p-4 bg-gray-900/50 rounded-xl border border-gray-700">
            <h3 className="text-sm font-semibold text-gray-400 mb-3">数据备份</h3>
            <div className="flex gap-3">
              <button
                onClick={handleExport}
                className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors"
              >
                <Download size={16} /> 导出JSON备份
              </button>
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors"
              >
                <Upload size={16} /> 导入JSON备份
              </button>
              <input
                ref={fileInputRef}
                type="file"
                accept=".json"
                onChange={handleImport}
                className="hidden"
              />
            </div>
          </div>

          <div className="mb-6">
            <h3 className="text-lg font-semibold text-gray-200 mb-3">
              {isCustomMode ? (customStages[0]?.name || '第一阶段') : 'N进16'} 选手名单
            </h3>

            <div className="flex gap-2 mb-4">
              <button
                onClick={() => setUseBulkMode(false)}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  !useBulkMode
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                <Users size={16} className="inline mr-1" /> 逐个添加
              </button>
              <button
                onClick={() => setUseBulkMode(true)}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  useBulkMode
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                }`}
              >
                批量导入
              </button>
            </div>

            {useBulkMode ? (
              <div>
                <textarea
                  value={bulkNameInput}
                  onChange={(e) => setBulkNameInput(e.target.value)}
                  placeholder="每行一个选手名称，例如：&#10;选手A&#10;选手B&#10;选手C"
                  className="w-full h-48 px-4 py-3 rounded-xl bg-gray-900 border border-gray-600 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500 resize-none"
                />
                <button
                  onClick={handleBulkAddPlayers}
                  className="mt-3 px-6 py-2.5 rounded-xl bg-gradient-to-r from-green-500 to-green-600 text-white font-bold hover:from-green-600 hover:to-green-700 transition-all flex items-center gap-2"
                >
                  <Save size={18} /> 导入选手
                </button>
              </div>
            ) : (
              <div className="flex gap-2">
                <input
                  type="text"
                  value={playerNameInput}
                  onChange={(e) => setPlayerNameInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleAddSinglePlayer()}
                  placeholder="输入选手名称"
                  className="flex-1 px-4 py-2.5 rounded-xl bg-gray-900 border border-gray-600 text-white placeholder-gray-500 focus:outline-none focus:border-blue-500"
                />
                <button
                  onClick={handleAddSinglePlayer}
                  className="px-6 py-2.5 rounded-xl bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors"
                >
                  添加
                </button>
              </div>
            )}
          </div>

          {/* 预览选手列表 */}
          {stages.n216.players.length > 0 && (
            <div className="mb-6">
              <h4 className="text-sm font-semibold text-gray-400 mb-2">
                已添加 {stages.n216.players.length} 名选手
              </h4>
              <div className="flex flex-wrap gap-2">
                {stages.n216.players.map((p) => (
                  <span
                    key={p.id}
                    className="px-3 py-1 rounded-full bg-gray-700 text-gray-200 text-sm flex items-center gap-1"
                  >
                    {p.seed && (
                      <span className="text-yellow-400 font-bold">#{p.seed}</span>
                    )}
                    {p.name}
                  </span>
                ))}
              </div>
            </div>
          )}

          {/* History section */}
          <div className="mb-6">
            <button
              onClick={() => setShowHistory(!showHistory)}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors"
            >
              <History size={16} /> {showHistory ? '收起历史记录' : '查看历史记录'}
            </button>
            {showHistory && (
              <div className="mt-3 p-4 bg-gray-900/50 rounded-xl border border-gray-700 max-h-64 overflow-y-auto">
                {historyList.length === 0 ? (
                  <p className="text-gray-500 text-sm">暂无历史记录</p>
                ) : (
                  <div className="space-y-2">
                    {historyList.map((h) => (
                      <div key={h.id} className="flex items-center justify-between p-3 bg-gray-800 rounded-lg">
                        <div>
                          <span className="text-white font-medium">{h.champion}</span>
                          <span className="text-gray-400 text-sm ml-3">{h.date}</span>
                        </div>
                        <button
                          onClick={() => deleteHistoryRecord(h.id)}
                          className="text-red-400 hover:text-red-300"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    ))}
                    <button
                      onClick={clearHistory}
                      className="text-red-400 hover:text-red-300 text-sm mt-2"
                    >
                      清空所有历史
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>

          <button
            onClick={handleStartTournament}
            className="w-full py-4 rounded-xl bg-gradient-to-r from-yellow-500 to-orange-500 text-white font-black text-lg hover:from-yellow-600 hover:to-orange-600 transition-all flex items-center justify-center gap-3"
          >
            <Play size={24} /> 开始赛事
          </button>
        </div>

        {/* 自定义阶段编辑器弹窗 */}
        {showCustomStageEditor && (
          <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-2xl p-6 border border-gray-700 w-full max-w-2xl max-h-[80vh] overflow-y-auto">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-white flex items-center gap-2">
                  <LayoutList size={20} className="text-purple-400" />
                  编辑自定义阶段
                </h3>
                <button
                  onClick={handleCancelCustomStageEdit}
                  className="text-gray-400 hover:text-white transition-colors"
                >
                  <X size={20} />
                </button>
              </div>

              <div className="space-y-3 mb-4">
                {editingStages.map((stage, index) => (
                  <div key={stage.id} className="p-3 bg-gray-900/50 rounded-xl border border-gray-700">
                    <div className="flex items-center gap-2 mb-2">
                      <span className="text-sm font-bold text-gray-400">阶段 {index + 1}</span>
                      <button
                        onClick={() => handleRemoveCustomStage(stage.id)}
                        className="ml-auto text-red-400 hover:text-red-300 transition-colors"
                      >
                        <Minus size={16} />
                      </button>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                      <div>
                        <label className="text-xs text-gray-500 block mb-1">阶段名称</label>
                        <input
                          type="text"
                          value={stage.name}
                          onChange={(e) => handleUpdateCustomStage(stage.id, 'name', e.target.value)}
                          className="w-full px-2 py-1.5 rounded-lg bg-gray-800 border border-gray-600 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>
                      <div>
                        <label className="text-xs text-gray-500 block mb-1">参赛人数</label>
                        <input
                          type="number"
                          min="2"
                          value={stage.playerCount}
                          onChange={(e) => handleUpdateCustomStage(stage.id, 'playerCount', parseInt(e.target.value) || 2)}
                          className="w-full px-2 py-1.5 rounded-lg bg-gray-800 border border-gray-600 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>
                      <div>
                        <label className="text-xs text-gray-500 block mb-1">晋级人数</label>
                        <input
                          type="number"
                          min="1"
                          value={stage.advanceCount}
                          onChange={(e) => handleUpdateCustomStage(stage.id, 'advanceCount', parseInt(e.target.value) || 1)}
                          className="w-full px-2 py-1.5 rounded-lg bg-gray-800 border border-gray-600 text-white text-sm focus:outline-none focus:border-blue-500"
                        />
                      </div>
                    </div>
                  </div>
                ))}
              </div>

              <button
                onClick={handleAddCustomStage}
                className="w-full mb-3 px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors flex items-center justify-center gap-2"
              >
                <Plus size={16} /> 添加阶段
              </button>

              <div className="flex gap-3">
                <button
                  onClick={handleCancelCustomStageEdit}
                  className="flex-1 px-4 py-2 rounded-lg bg-gray-700 text-gray-300 hover:bg-gray-600 transition-colors"
                >
                  取消
                </button>
                <button
                  onClick={handleSaveCustomStages}
                  className="flex-1 px-4 py-2 rounded-lg bg-gradient-to-r from-purple-500 to-purple-600 text-white font-bold hover:from-purple-600 hover:to-purple-700 transition-all"
                >
                  保存配置
                </button>
              </div>
            </div>
          </div>
        )}

        {/* 模板管理弹窗 */}
        {showTemplateManager && (
          <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
            <div className="bg-gray-800 rounded-2xl p-6 border border-gray-700 w-full max-w-lg max-h-[80vh] overflow-y-auto">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-xl font-bold text-white flex items-center gap-2">
                  <FolderOpen size={20} className="text-blue-400" />
                  模板管理
                </h3>
                <button
                  onClick={() => setShowTemplateManager(false)}
                  className="text-gray-400 hover:text-white transition-colors"
                >
                  <X size={20} />
                </button>
              </div>

              {templates.length === 0 ? (
                <p className="text-gray-500 text-center py-8">暂无模板</p>
              ) : (
                <div className="space-y-2 mb-4">
                  {templates.map((t) => (
                    <div key={t.id} className="p-3 bg-gray-900/50 rounded-xl border border-gray-700 flex items-center justify-between">
                      <div className="flex-1 min-w-0">
                        <div className="text-white font-medium truncate">{t.name}</div>
                        <div className="text-gray-500 text-xs">
                          {new Date(t.createdAt).toLocaleString()} · {t.isCustomMode ? '自定义赛制' : '固定赛制'}
                          {t.n216PlayerNames.length > 0 && ` · ${t.n216PlayerNames.length}名选手`}
                        </div>
                      </div>
                      <div className="flex gap-2 ml-3">
                        <button
                          onClick={() => handleLoadTemplate(t.id)}
                          className="px-3 py-1.5 rounded-lg bg-blue-600/30 text-blue-300 border border-blue-500/30 hover:bg-blue-600/50 transition-colors text-sm flex items-center gap-1"
                        >
                          <FolderOpen size={12} /> 加载
                        </button>
                        <button
                          onClick={() => handleDeleteTemplate(t.id)}
                          className="px-3 py-1.5 rounded-lg bg-red-600/30 text-red-300 border border-red-500/30 hover:bg-red-600/50 transition-colors text-sm flex items-center gap-1"
                        >
                          <Trash2 size={12} />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        )}

        {/* 签到面板弹窗 */}
        {showCheckInPanel && (() => {
          const checkinUrl = `${window.location.origin}/checkin`
          return (
            <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 p-4">
              <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 max-w-sm w-full text-center">
                <h3 className="text-xl font-bold text-white mb-2 flex items-center justify-center gap-2">
                  <QrCode className="text-cyan-400" size={24} />
                  扫码签到
                </h3>
                <p className="text-sm text-gray-400 mb-4">
                  选手扫描二维码后，在签到页输入名字
                </p>

                <div className="bg-white p-4 rounded-xl inline-block mb-4">
                  <QRCodeSVG value={checkinUrl} size={200} level="M" />
                </div>

                <div className="flex items-center gap-2 mb-4">
                  <input
                    type="text"
                    readOnly
                    value={checkinUrl}
                    className="flex-1 px-3 py-2 rounded-lg bg-gray-900 border border-gray-600 text-gray-400 text-xs font-mono focus:outline-none"
                  />
                  <button
                    onClick={() => {
                      navigator.clipboard.writeText(checkinUrl)
                      alert('链接已复制')
                    }}
                    className="px-3 py-2 rounded-lg bg-gray-700 text-gray-300 hover:bg-gray-600 transition-colors text-sm"
                  >
                    复制
                  </button>
                </div>

                <button
                  onClick={() => setShowCheckInPanel(false)}
                  className="w-full px-4 py-2.5 rounded-xl bg-gray-700 text-gray-300 hover:bg-gray-600 transition-colors font-bold"
                >
                  关闭
                </button>
              </div>
            </div>
          )
        })()}
      </div>
    )
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      {/* Timer Section */}
      <div className="mb-6 bg-gray-800 rounded-2xl p-4 border border-gray-700">
        <div className="flex items-center gap-3 flex-wrap">
          <Clock size={20} className="text-yellow-400" />
          <span className="text-lg font-bold text-white">赛事计时器</span>
          {timerRunning || timerSeconds > 0 ? (
            <div className="flex items-center gap-3 ml-auto">
              <span className={`font-mono text-2xl font-black ${timerSeconds <= 10 && timerRunning ? 'text-red-400 animate-pulse' : 'text-yellow-400'}`}>
                {formatTime(timerSeconds)}
              </span>
              {timerLabel && <span className="text-gray-400 text-sm">{timerLabel}</span>}
              {timerRunning ? (
                <button
                  onClick={stopTimer}
                  className="px-3 py-1.5 rounded-lg bg-yellow-600/30 text-yellow-300 border border-yellow-500/30 hover:bg-yellow-600/50 transition-colors text-sm"
                >
                  暂停
                </button>
              ) : (
                timerSeconds > 0 && (
                  <button
                    onClick={() => startTimer(timerLabel, timerSeconds)}
                    className="px-3 py-1.5 rounded-lg bg-green-600/30 text-green-300 border border-green-500/30 hover:bg-green-600/50 transition-colors text-sm"
                  >
                    继续
                  </button>
                )
              )}
              <button
                onClick={resetTimer}
                className="px-3 py-1.5 rounded-lg bg-red-600/30 text-red-300 border border-red-500/30 hover:bg-red-600/50 transition-colors text-sm"
              >
                重置
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-2 ml-auto">
              <input
                type="text"
                value={timerCustomLabel}
                onChange={(e) => setTimerCustomLabel(e.target.value)}
                placeholder="标签(可选)"
                className="w-24 px-2 py-1 rounded-lg bg-gray-900 border border-gray-600 text-white text-sm placeholder-gray-500 focus:outline-none focus:border-blue-500"
              />
              <input
                type="number"
                min="0"
                max="59"
                value={timerInputMin}
                onChange={(e) => setTimerInputMin(parseInt(e.target.value) || 0)}
                placeholder="分"
                className="w-16 px-2 py-1 rounded-lg bg-gray-900 border border-gray-600 text-white text-sm font-mono focus:outline-none focus:border-blue-500"
              />
              <span className="text-gray-400">分</span>
              <input
                type="number"
                min="0"
                max="59"
                value={timerInputSec}
                onChange={(e) => setTimerInputSec(parseInt(e.target.value) || 0)}
                placeholder="秒"
                className="w-16 px-2 py-1 rounded-lg bg-gray-900 border border-gray-600 text-white text-sm font-mono focus:outline-none focus:border-blue-500"
              />
              <span className="text-gray-400">秒</span>
              <button
                onClick={handleStartTimer}
                className="px-4 py-1.5 rounded-lg bg-gradient-to-r from-yellow-500 to-orange-500 text-white font-bold text-sm hover:from-yellow-600 hover:to-orange-600 transition-all"
              >
                开始计时
              </button>
            </div>
          )}
        </div>
      </div>

      {/* 阶段导航 */}
      <div className="mb-6">
        <div className="flex items-center gap-2 flex-wrap">
          {STAGE_ORDER.map((stage, idx) => {
            const isCompleted = stages[stage].locked && stages[stage].players.length > 0
            const isCurrent = stage === currentStage
            const isAvailable = idx === 0 || (stages[STAGE_ORDER[idx - 1]].locked && stages[STAGE_ORDER[idx - 1]].players.length > 0)

            return (
              <div key={stage} className="flex items-center">
                <button
                  onClick={() => isAvailable && setCurrentStage(stage)}
                  disabled={!isAvailable}
                  className={`px-4 py-2 rounded-xl font-bold transition-all ${
                    isCurrent
                      ? 'bg-blue-600 text-white shadow-lg'
                      : isCompleted
                      ? 'bg-green-600/30 text-green-300 border border-green-500/30'
                      : isAvailable
                      ? 'bg-gray-700 text-gray-300 hover:bg-gray-600'
                      : 'bg-gray-800 text-gray-600 cursor-not-allowed'
                  }`}
                >
                  {getStageLabel(stage)}
                  {isCompleted && <span className="ml-1">✓</span>}
                </button>
                {idx < STAGE_ORDER.length - 1 && (
                  <ChevronRight size={16} className="text-gray-500" />
                )}
              </div>
            )
          })}
        </div>
      </div>

      {/* 操作栏 */}
      <div className="bg-gray-800 rounded-2xl p-4 mb-6 border border-gray-700 flex flex-wrap gap-3 items-center justify-between">
        <div className="flex items-center gap-3">
          <h3 className="text-lg font-bold text-white">
            {stageLabel}
          </h3>
          <span className="text-sm text-gray-400">
            {stageData.players.length} 名选手 · 前 {advanceCount} 名晋级
          </span>
          {isCustomMode && (
            <span className="px-2 py-0.5 rounded bg-purple-600/30 text-purple-300 text-xs border border-purple-500/30">
              自定义赛制
            </span>
          )}
        </div>
        <div className="flex gap-2 flex-wrap">
          {stageData.locked ? (
            <>
              <button
                onClick={() => toggleStageLock(currentStage)}
                className="px-4 py-2 rounded-lg bg-yellow-600/30 text-yellow-300 border border-yellow-500/30 hover:bg-yellow-600/50 transition-colors flex items-center gap-2"
              >
                <Unlock size={16} /> 解锁修改
              </button>
              {stageIndex < STAGE_ORDER.length - 1 && (
                <button
                  onClick={handleNextStage}
                  className="px-4 py-2 rounded-lg bg-gradient-to-r from-blue-500 to-blue-600 text-white font-bold hover:from-blue-600 hover:to-blue-700 transition-all flex items-center gap-2"
                >
                  <ArrowRight size={16} /> 进入下一阶段
                </button>
              )}
            </>
          ) : (
            <button
              onClick={handleCalculateRankings}
              className="px-4 py-2 rounded-lg bg-gradient-to-r from-green-500 to-green-600 text-white font-bold hover:from-green-600 hover:to-green-700 transition-all flex items-center gap-2"
            >
              <Trophy size={16} /> 计算排名
            </button>
          )}
          <button
            onClick={handleBroadcast}
            className="px-4 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors flex items-center gap-2"
          >
            <Save size={16} /> 同步到OBS
          </button>
          <button
            onClick={handleSaveHistory}
            className="px-4 py-2 rounded-lg bg-purple-600/30 text-purple-300 border border-purple-500/30 hover:bg-purple-600/50 transition-colors flex items-center gap-2"
          >
            <History size={16} /> 保存历史
          </button>
          <button
            onClick={handleExport}
            className="px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors flex items-center gap-2"
          >
            <Download size={16} /> 导出
          </button>
          <button
            onClick={() => fileInputRef.current?.click()}
            className="px-4 py-2 rounded-lg bg-gray-700 text-gray-200 hover:bg-gray-600 transition-colors flex items-center gap-2"
          >
            <Upload size={16} /> 导入
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".json"
            onChange={handleImport}
            className="hidden"
          />
          <button
            onClick={handleReset}
            className="px-4 py-2 rounded-lg bg-red-600/30 text-red-300 border border-red-500/30 hover:bg-red-600/50 transition-colors flex items-center gap-2"
          >
            <RotateCcw size={16} /> 重置
          </button>
        </div>
      </div>

      {/* 种子排序操作栏 */}
      {!stageData.locked && (
        <div className="bg-gray-800 rounded-2xl p-4 mb-6 border border-gray-700 flex flex-wrap gap-3 items-center">
          <Hash size={18} className="text-yellow-400" />
          <span className="text-sm font-semibold text-gray-300">种子排序</span>
          <button
            onClick={handleApplySeeding}
            className="px-4 py-2 rounded-lg bg-gradient-to-r from-yellow-500 to-orange-500 text-white font-bold text-sm hover:from-yellow-600 hover:to-orange-600 transition-all flex items-center gap-2"
          >
            <Hash size={14} /> 应用标准种子排序
          </button>
          <span className="text-xs text-gray-500">
            已设置种子排名的选手将按标准 bracket 分配位置，未设置种子的选手随机填充
          </span>
        </div>
      )}

      {/* 分数表格 */}
      <div className="bg-gray-800 rounded-2xl border border-gray-700 overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="bg-gray-900/50">
              <th className="px-4 py-3 text-left text-sm font-bold text-gray-400 w-16">排名</th>
              <th className="px-4 py-3 text-left text-sm font-bold text-gray-400 w-16">种子</th>
              <th className="px-4 py-3 text-left text-sm font-bold text-gray-400">选手</th>
              <th className="px-4 py-3 text-right text-sm font-bold text-gray-400 w-40">完成率</th>
              <th className="px-4 py-3 text-right text-sm font-bold text-gray-400 w-40">DX分数</th>
            </tr>
          </thead>
          <tbody>
            {stageData.players.map((player, index) => (
              <tr
                key={player.id}
                className={`border-t border-gray-700/50 transition-colors ${
                  index % 2 === 0 ? 'bg-gray-800' : 'bg-gray-800/50'
                }`}
              >
                <td className="px-4 py-3">
                  {player.rank !== null ? (
                    <span
                      className={`inline-flex items-center justify-center w-8 h-8 rounded-full font-black ${
                        player.rank === 1
                          ? 'bg-yellow-500 text-yellow-900'
                          : player.rank === 2
                          ? 'bg-gray-400 text-gray-800'
                          : player.rank === 3
                          ? 'bg-orange-600 text-orange-100'
                          : 'bg-gray-700 text-gray-300'
                      }`}
                    >
                      {player.rank}
                    </span>
                  ) : (
                    <span className="text-gray-500">-</span>
                  )}
                </td>
                <td className="px-4 py-3">
                  {stageData.locked ? (
                    <span className="text-yellow-400 font-mono text-sm">
                      {player.seed !== undefined && player.seed !== null ? `#${player.seed}` : '-'}
                    </span>
                  ) : (
                    <input
                      type="number"
                      min="1"
                      value={player.seed ?? ''}
                      onChange={(e) => {
                        const val = e.target.value
                        if (val === '') {
                          setPlayerSeed(currentStage, player.id, null)
                        } else {
                          const num = parseInt(val)
                          if (!isNaN(num) && num > 0) {
                            setPlayerSeed(currentStage, player.id, num)
                          }
                        }
                      }}
                      placeholder="#"
                      className="w-16 px-2 py-1 rounded-lg bg-gray-900 border border-gray-600 text-yellow-400 font-mono text-sm focus:outline-none focus:border-yellow-500"
                    />
                  )}
                </td>
                <td className="px-4 py-3">
                  <span className="text-white font-medium">{player.name}</span>
                </td>
                <td className="px-4 py-3">
                  {stageData.locked ? (
                    <span className="text-right block text-white font-mono">
                      {player.score !== null ? player.score.toFixed(4) : '-'}
                    </span>
                  ) : (
                    <input
                      type="number"
                      step="0.0001"
                      min="0"
                      max="500"
                      value={player.score ?? ''}
                      onChange={(e) => handleScoreChange(player.id, e.target.value)}
                      placeholder="0.0000"
                      className="w-full text-right px-3 py-1.5 rounded-lg bg-gray-900 border border-gray-600 text-white font-mono focus:outline-none focus:border-blue-500"
                    />
                  )}
                </td>
                <td className="px-4 py-3">
                  {stageData.locked ? (
                    <span className="text-right block text-blue-300 font-mono">
                      {player.dxScore || '-'}
                    </span>
                  ) : (
                    <input
                      type="text"
                      value={player.dxScore}
                      onChange={(e) => updatePlayer(currentStage, player.id, { dxScore: e.target.value })}
                      placeholder="自由填写"
                      className="w-full text-right px-3 py-1.5 rounded-lg bg-gray-900 border border-gray-600 text-blue-300 focus:outline-none focus:border-blue-500"
                    />
                  )}
                </td>
              </tr>
            ))}
            {stageData.players.length === 0 && (
              <tr>
                <td colSpan={5} className="px-4 py-8 text-center text-gray-500">
                  暂无选手
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 上一阶段晋级选手单元块展示 */}
      {stageIndex > 0 && (() => {
        const prevStage = STAGE_ORDER[stageIndex - 1]
        const prevStageData = stages[prevStage]
        if (!prevStageData || prevStageData.players.length === 0) return null
        const advancedPlayers = prevStageData.players
          .filter((p) => p.advanced)
          .sort((a, b) => (a.rank ?? 999) - (b.rank ?? 999))
        if (advancedPlayers.length === 0) return null

        return (
          <div className="mt-6 bg-gray-800 rounded-2xl p-6 border border-green-500/30">
            <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
              <Trophy className="text-yellow-400" size={22} />
              {getStageLabel(prevStage)} 晋级名单（前 {getAdvanceCount(prevStage)} 名）
            </h3>
            <div className="flex flex-wrap gap-3">
              {advancedPlayers.map((p) => (
                <div
                  key={p.id}
                  className={`flex flex-col items-center gap-2 px-5 py-4 rounded-xl min-w-[140px] ${
                    prevStage === '16to8'
                      ? 'bg-gradient-to-b from-blue-900/40 to-gray-800 border-2 border-blue-400/50'
                      : 'bg-gradient-to-b from-green-900/40 to-gray-800 border border-green-500/40'
                  }`}
                >
                  {prevStage === '16to8' && (
                    <span className="px-2 py-0.5 rounded-full bg-blue-500/30 border border-blue-400/50 text-blue-300 text-xs font-bold">
                      8强
                    </span>
                  )}
                  <span className={`w-10 h-10 rounded-full font-black flex items-center justify-center ${
                    p.rank === 1 ? 'bg-yellow-500 text-yellow-900' :
                    p.rank === 2 ? 'bg-gray-400 text-gray-800' :
                    p.rank === 3 ? 'bg-orange-600 text-orange-100' :
                    'bg-gray-700 text-gray-300'
                  }`}>
                    {p.rank}
                  </span>
                  <span className="text-white font-bold text-center">{p.name}</span>
                  <span className="text-green-300 font-mono text-sm">{(p.score ?? 0).toFixed(4)}</span>
                  {p.dxScore && (
                    <span className="text-blue-300 font-mono text-xs">DX: {p.dxScore}</span>
                  )}
                </div>
              ))}
            </div>
          </div>
        )
      })()}

      {/* 当前阶段已锁定：显示晋级单元块 */}
      {stageData.locked && stageData.players.filter((p) => p.advanced).length > 0 && (
        <div className="mt-6 bg-gray-800 rounded-2xl p-6 border border-green-500/30">
          <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
            <Trophy className="text-yellow-400" size={22} />
            {stageLabel} 晋级名单（前 {advanceCount} 名）
          </h3>
          <div className="flex flex-wrap gap-3">
            {stageData.players
              .filter((p) => p.advanced)
              .sort((a, b) => (a.rank ?? 999) - (b.rank ?? 999))
              .map((p) => (
                <div
                  key={p.id}
                  className="flex flex-col items-center gap-2 px-5 py-4 rounded-xl bg-gradient-to-b from-green-900/40 to-gray-800 border border-green-500/40 min-w-[140px]"
                >
                  <span className={`w-10 h-10 rounded-full font-black flex items-center justify-center ${
                    p.rank === 1 ? 'bg-yellow-500 text-yellow-900' :
                    p.rank === 2 ? 'bg-gray-400 text-gray-800' :
                    p.rank === 3 ? 'bg-orange-600 text-orange-100' :
                    'bg-gray-700 text-gray-300'
                  }`}>
                    {p.rank}
                  </span>
                  <span className="text-white font-bold text-center">{p.name}</span>
                  <span className="text-green-300 font-mono text-sm">{(p.score ?? 0).toFixed(4)}</span>
                  {p.dxScore && (
                    <span className="text-blue-300 font-mono text-xs">DX: {p.dxScore}</span>
                  )}
                </div>
              ))}
          </div>
        </div>
      )}
    </div>
  )
}
