import { useState, useEffect } from 'react'
import { CheckCircle2, X, Send } from 'lucide-react'

export default function CheckInPage() {
  const [name, setName] = useState('')
  const [submitted, setSubmitted] = useState(false)
  const [error, setError] = useState('')

  // Listen for existing check-in channel (for the checkin page itself)
  const handleSubmit = () => {
    const trimmedName = name.trim()
    if (!trimmedName) {
      setError('请输入你的名字')
      return
    }
    if (trimmedName.length > 20) {
      setError('名字不能超过20个字符')
      return
    }

    // Broadcast check-in name to all tabs
    try {
      const channel = new BroadcastChannel('tournament-sync')
      channel.postMessage({
        type: 'checkin',
        payload: { name: trimmedName },
      })
      channel.close()
      setSubmitted(true)
    } catch {
      setError('签到失败，请重试')
    }
  }

  const handleReset = () => {
    setName('')
    setSubmitted(false)
    setError('')
  }

  return (
    <div className="min-h-screen bg-gray-900 flex items-center justify-center px-4">
      <div className="w-full max-w-md">
        <div className="bg-gray-800 rounded-2xl p-8 border border-gray-700 shadow-2xl">
          <div className="text-center mb-6">
            <h1 className="text-2xl font-black text-white mb-2">选手签到</h1>
            <p className="text-gray-400 text-sm">输入你的名字完成签到</p>
          </div>

          {submitted ? (
            <div className="text-center py-8">
              <CheckCircle2 size={64} className="mx-auto mb-4 text-green-400" />
              <h2 className="text-xl font-bold text-white mb-2">签到成功！</h2>
              <p className="text-gray-400 mb-6">你的名字已记录</p>
              <button
                onClick={handleReset}
                className="px-6 py-2.5 rounded-xl bg-gray-700 text-gray-300 hover:bg-gray-600 transition-colors font-bold"
              >
                继续签到
              </button>
            </div>
          ) : (
            <>
              {error && (
                <div className="mb-4 p-3 rounded-lg bg-red-600/20 border border-red-500/30 text-red-300 text-sm flex items-center gap-2">
                  <X size={14} />
                  {error}
                </div>
              )}

              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-semibold text-gray-300 mb-2">选手名字</label>
                  <input
                    type="text"
                    value={name}
                    onChange={(e) => {
                      setName(e.target.value)
                      setError('')
                    }}
                    onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
                    placeholder="请输入你的参赛名字"
                    maxLength={20}
                    className="w-full px-4 py-3 rounded-xl bg-gray-900 border border-gray-600 text-white placeholder-gray-500 text-lg focus:outline-none focus:border-cyan-500 transition-colors"
                    autoFocus
                  />
                </div>

                <button
                  onClick={handleSubmit}
                  className="w-full py-3.5 rounded-xl bg-gradient-to-r from-cyan-500 to-blue-600 text-white font-black text-lg hover:from-cyan-600 hover:to-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  <Send size={20} /> 确认签到
                </button>
              </div>
            </>
          )}
        </div>

        <p className="text-center text-gray-600 text-xs mt-4">
          赛事签到系统
        </p>
      </div>
    </div>
  )
}
